source_id": "sa-4.2_gdn", "text_sha256": "80be6357ba19a9281565ec7af94a662e0fc87fe434c714c910a2d707b0f849df"}, {"position": "14", "source_id": "sa-4.3_gdn", "text_sha256": "9b555c2cfbe3a0dc9c07c9bc8e34fb7f910bbc3d1dfbd1eaba2b3891fa894f92"}, {"position": "15", "source_id": "sa-4.9_gdn", "text_sha256": "fc8f8a2d790489e2f34959ab20f92f7af1dc9c59c2bab5bc17c4f547c227d640"}], "schema_version": "rq2-evidence-window-v1", "sha256": "5d5055ee0e0296ec3f4b4961cef2f9f8e2e2636ad2d999040043575cc9d492a8", "source_ids": ["sa-4_smt", "sa-4_smt.c", "sa-4_smt.d", "sa-4_smt.e", "sa-4_smt.a", "sa-4_smt.b", "sa-4_smt.g", "sa-4_smt.f", "sa-4.2_smt", "sa-4.3_smt", "sa-4.9_smt", "sa-4.10_smt", "sa-4_gdn", "sa-4.2_gdn", "sa-4.3_gdn", "sa-4.9_gdn"]}, "fallback_used": false, "hierarchy_closure_used": false, "per_identifier_provenance": [{"source": "frozen_window", "source_id": "sa-4_smt"}, {"source": "frozen_window", "source_id": "sa-4_smt.c"}, {"source": "frozen_window", "source_id": "sa-4_smt.d"}, {"source": "frozen_window", "source_id": "sa-4_smt.e"}, {"source": "frozen_window", "source_id": "sa-4_smt.a"}, {"source": "frozen_window", "source_id": "sa-4_smt.b"}, {"source": "frozen_window", "source_id": "sa-4_smt.g"}, {"source": "frozen_window", "source_id": "sa-4_smt.f"}, {"source": "frozen_window", "source_id": "sa-4.2_smt"}, {"source": "frozen_window", "source_id": "sa-4.3_smt"}, {"source": "frozen_window", "source_id": "sa-4.9_smt"}, {"source": "frozen_window", "source_id": "sa-4.10_smt"}, {"source": "frozen_window", "source_id": "sa-4_gdn"}, {"source": "frozen_window", "source_id": "sa-4.2_gdn"}, {"source": "frozen_window", "source_id": "sa-4.3_gdn"}, {"source": "frozen_window", "source_id": "sa-4.9_gdn"}], "prepared_context_sha256": "699f47f632744ac6df7b5e0287d48b18f1d018de11005acf23c297a3383bcbd1", "rescue_used": false, "result_id": "rq2_no_selector_v1", "selector_called": false, "selector_policy": "bypassed_retain_entire_frozen_window"}, "evidence_spans": [{"source_id": "sa-4_smt", "span_text": "The organization includes the following requirements, descriptions, and criteria, explicitly or by reference, in the acquisition contract for the information system, system component, or information system service in accordance with applicable federal laws, Executive Orders, directives, policies, regulations, standards, guidelines, and organizational mission/business needs: a. Security functional requirements; b. Security strength requirements; c. Security assurance requirements; d. Security-related documentation requirements; e. Requirements for protecting security-related documentation; f. Description of the information system development environment and environment in which the system is intended to operate; and g. Acceptance criteria."}, {"source_id": "sa-4_smt.c", "span_text": "Security assurance requirements;"}, {"source_id": "sa-4_smt.d", "span_text": "Security-related documentation requirements;"}, {"source_id": "sa-4_smt.e", "span_text": "Requirements for protecting security-related documentation;"}, {"source_id": "sa-4_smt.a", "span_text": "Security functional requirements;"}, {"source_id": "sa-4_smt.b", "span_text": "Security strength requirements;"}, {"source_id": "sa-4_smt.g", "span_text": "Acceptance criteria."}, {"source_id": "sa-4_smt.f", "span_text": "Description of the information system development environment and environment in which the system is intended to operate; and"}, {"source_id": "sa-4.2_smt", "span_text": "The organization requires the developer of the information system, system component, or information system service to provide design and implementation information for the security controls to be employed that includes: {{ insert: param, sa-4.2_prm_1 }} at {{ insert: param, sa-4.2_prm_3 }}."}, {"source_id": "sa-4.3_smt", "span_text": "The organization requires the developer of the information system, system component, or information system service to demonstrate the use of a system development life cycle that includes {{ insert: param, sa-4.3_prm_1 }}."}, {"source_id": "sa-4.9_smt", "span_text": "The organization requires the developer of the information system, system component, or information system service to identify early in the system development life cycle, the functions, ports, protocols, and services intended for organizational use."}, {"source_id": "sa-4.10_smt", "span_text": "The organization employs only information technology products on the FIPS 201-approved products list for Personal Identity Verification (PIV) capability implemented within organizational information systems."}, {"source_id": "sa-4_gdn", "span_text": "Information system components are discrete, identifiable information technology assets (e.g., hardware, software, or firmware) that represent the building blocks of an information system. Information system components include commercial information technology products. Security functional requirements include security capabilities, security functions, and security mechanisms. Security strength requirements associated with such capabilities, functions, and mechanisms include degree of correctness, completeness, resistance to direct attack, and resistance to tampering or bypass. Security assurance requirements include: (i) development processes, procedures, practices, and methodologies; and (ii) evidence from development and assessment activities providing grounds for confidence that the required security functionality has been implemented and the required security strength has been achieved. Security documentation requirements address all phases of the system development life cycle. Security functionality, assurance, and documentation requirements are expressed in terms of security controls and control enhancements that have been selected through the tailoring process. The security control tailoring process includes, for example, the specification of parameter values through the use of assignment and selection statements and the specification of platform depe